import"./chunk-VC46IEJQ.js";var e=(r,n,s,t,a)=>({name:r,desc:n,tour:s,source:t,...a?{spoiler:a}:{}}),o={id:"myr",intro:{en:"A city of glassmakers, lens-grinders, lacemakers and carpet-weavers on the Sea of Myrth, ruled by a conclave of wealthy magisters who fight their wars with hired companies. This is an orderly, walled, gridded Myr of the imagination.",zh:"\u5BC6\u5C14\u5750\u843D\u5728\u5BC6\u5C14\u65AF\u6D77\u7554\uFF0C\u73BB\u7483\u5320\u3001\u78E8\u955C\u5E08\u3001\u857E\u4E1D\u5320\u4E0E\u7EC7\u6BEF\u5320\u4E91\u96C6\u3002\u57CE\u90A6\u7531\u5BCC\u6709\u7684\u603B\u7763\u8BAE\u4F1A\u7EDF\u6CBB\uFF0C\u6253\u4ED7\u9760\u96C7\u4F63\u5175\u56E2\u3002\u773C\u524D\u8FD9\u5EA7\u57CE\u5899\u73AF\u7ED5\u3001\u8857\u9053\u65B9\u6B63\u7684\u5BC6\u5C14\uFF0C\u51FA\u81EA\u60F3\u8C61\u3002"},notes:{en:"From the novels: Myrish lenses and far-eyes, glass, lace and carpets; Myrish sellswords and crossbowmen. From TWOIAF and wiki summaries: Myr on the Sea of Myrth near the Disputed Lands, ruled by magisters, warring with Lys and Tyrosh through free companies, with slaves outnumbering the freeborn. Almost nothing is known of its layout, so the grid plan, walls, harbour moles, buildings and mercenary camps are interpretation. The scene does not depict slavery.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u5BC6\u5C14\u7684\u955C\u7247\u4E0E\u8FDC\u955C\u3001\u73BB\u7483\u3001\u857E\u4E1D\u4E0E\u5730\u6BEF\uFF0C\u4EE5\u53CA\u5BC6\u5C14\u4F63\u5175\u548C\u5F29\u624B\u3002\u51FA\u81EA\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u53CA\u7EF4\u57FA\u6458\u8981\uFF1A\u5BC6\u5C14\u4E34\u5BC6\u5C14\u65AF\u6D77\u3001\u8FD1\u4E89\u8BAE\u4E4B\u5730\uFF0C\u7531\u603B\u7763\u7EDF\u6CBB\uFF0C\u501F\u81EA\u7531\u4F63\u5175\u56E2\u4E0E\u91CC\u65AF\u3001\u6CF0\u6D1B\u897F\u4E89\u6218\uFF0C\u5974\u96B6\u4EBA\u6570\u591A\u4E8E\u81EA\u7531\u6C11\u3002\u57CE\u5E02\u5E03\u5C40\u51E0\u65E0\u8BB0\u8F7D\uFF0C\u56E0\u6B64\u65B9\u683C\u8857\u9053\u3001\u57CE\u5899\u3001\u9632\u6CE2\u5824\u3001\u5404\u5904\u5EFA\u7B51\u4E0E\u4F63\u5175\u8425\u5730\u5747\u5C5E\u6F14\u7ECE\u3002\u672C\u573A\u666F\u672A\u5448\u73B0\u5974\u96B6\u5236\u3002"},tour:["sheltered-bay","city-walls","market-square","magisters-hall","lens-makers-quarter","myrish-eye-tower","glassworks","carpet-weavers","mercenary-camps"],sources:[{ref:"awoiaf",checked:"search-snippet",note:{en:"Lenses, glass, mirrors, lace and carpets; a conclave of magisters; three slaves to every freeborn; hired companies in the Disputed Lands wars; the Sea of Myrth: from web-search summaries (pages not fetched). No description of walls or layout was found.",zh:"\u955C\u7247\u3001\u73BB\u7483\u3001\u955C\u5B50\u3001\u857E\u4E1D\u4E0E\u5730\u6BEF\uFF1B\u603B\u7763\u8BAE\u4F1A\uFF1B\u5974\u96B6\u4E0E\u81EA\u7531\u6C11\u4E4B\u6BD4\u4E3A\u4E09\u6BD4\u4E00\uFF1B\u4E89\u8BAE\u4E4B\u5730\u6218\u4E8B\u4E2D\u96C7\u7528\u4F63\u5175\u56E2\uFF1B\u5BC6\u5C14\u65AF\u6D77\uFF1A\u636E\u7F51\u7EDC\u641C\u7D22\u6458\u8981\uFF08\u672A\u80FD\u6253\u5F00\u9875\u9762\uFF09\u3002\u672A\u627E\u5230\u4EFB\u4F55\u5173\u4E8E\u57CE\u5899\u6216\u5E03\u5C40\u7684\u63CF\u5199\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"Location on the Sea of Myrth and the old Triarchy with Lys and Tyrosh: search summary only.",zh:"\u4F4D\u4E8E\u5BC6\u5C14\u65AF\u6D77\u7554\uFF0C\u4EE5\u53CA\u6614\u65E5\u4E0E\u91CC\u65AF\u3001\u6CF0\u6D1B\u897F\u7ED3\u6210\u7684\u201C\u4E09\u5973\u513F\u738B\u56FD\u201D\uFF1A\u4EC5\u636E\u641C\u7D22\u6458\u8981\u3002"}},{ref:"asos",checked:"memory",note:{en:"Myrish lenses and far-eyes in use in Westeros, as far as the Wall, recalled from memory; not re-read.",zh:"\u7EF4\u65AF\u7279\u6D1B\u4E43\u81F3\u957F\u57CE\u4E0A\u90FD\u5728\u7528\u5BC6\u5C14\u955C\u7247\u4E0E\u8FDC\u955C\uFF0C\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u3002"}}],landmarks:{"sheltered-bay":e({en:"Sheltered Bay",zh:"\u907F\u98CE\u6D77\u6E7E"},{en:"Two long stone moles enclose the harbour, leaving one gap for ships.",zh:"\u4E24\u9053\u957F\u957F\u7684\u77F3\u780C\u9632\u6CE2\u5824\u56F4\u51FA\u6E2F\u6C60\uFF0C\u53EA\u7559\u4E00\u4E2A\u7F3A\u53E3\u4F9B\u8239\u53EA\u51FA\u5165\u3002"},{en:"The moles turn an open shore into a quiet basin.",zh:"\u9632\u6CE2\u5824\u628A\u4E00\u7EBF\u5F00\u9614\u6D77\u5CB8\u56F4\u6210\u4E86\u5E73\u9759\u7684\u6E2F\u6C60\u3002"},{confidence:"medium",refs:["maps","twoiaf"],book:{en:"Myr is a port on the east shore of the Sea of Myrth (maps and search summaries); no harbour is described.",zh:"\u5BC6\u5C14\u662F\u5BC6\u5C14\u65AF\u6D77\u4E1C\u5CB8\u7684\u6E2F\u57CE\uFF08\u636E\u5730\u56FE\u4E0E\u641C\u7D22\u6458\u8981\uFF09\uFF1B\u4E66\u4E2D\u672A\u63CF\u5199\u5176\u6E2F\u53E3\u3002"},unknown:{en:"The harbour's real shape.",zh:"\u6E2F\u53E3\u7684\u771F\u5B9E\u5F62\u72B6\u3002"},interpretation:{en:"Straight quays and two towered moles, to suit an orderly city.",zh:"\u7B14\u76F4\u7684\u7801\u5934\u4E0E\u4E24\u9053\u5E26\u5854\u7684\u9632\u6CE2\u5824\uFF0C\u4E0E\u8FD9\u5EA7\u4E95\u7136\u6709\u5E8F\u7684\u57CE\u5E02\u76F8\u79F0\u3002"}}),"city-walls":e({en:"City Walls",zh:"\u57CE\u5899"},{en:"A regular rectangle of brick wall with evenly spaced towers and three land gates.",zh:"\u89C4\u6574\u7684\u77E9\u5F62\u7816\u5899\uFF0C\u5854\u697C\u7B49\u8DDD\u6392\u5217\uFF0C\u9646\u4FA7\u5F00\u4E09\u5EA7\u57CE\u95E8\u3002"},{en:"Orderly walls for an orderly city, with teal-roofed towers.",zh:"\u4E95\u7136\u4E4B\u57CE\u914D\u4E95\u7136\u4E4B\u5899\uFF0C\u5854\u697C\u8986\u7740\u9752\u7EFF\u5C4B\u9876\u3002"},{confidence:"low",refs:["twoiaf"],book:{en:"Nothing specific about Myr's walls was found in the sources checked.",zh:"\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u89C1\u4EFB\u4F55\u5173\u4E8E\u5BC6\u5C14\u57CE\u5899\u7684\u5177\u4F53\u8BB0\u8F7D\u3002"},unknown:{en:"All of it.",zh:"\u4E00\u6982\u4E0D\u77E5\u3002"},interpretation:{en:"The rectangle is invented, chosen to set Myr apart from the other Free Cities.",zh:"\u77E9\u5F62\u5E03\u5C40\u7CFB\u81EA\u62DF\uFF0C\u7528\u4EE5\u533A\u522B\u4E8E\u5176\u4ED6\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u3002"}}),"market-square":e({en:"Market Square",zh:"\u5E02\u96C6\u5E7F\u573A"},{en:"A paved square lined with awninged stalls at the centre of the grid.",zh:"\u65B9\u683C\u8857\u533A\u6B63\u4E2D\u7684\u77F3\u94FA\u5E7F\u573A\uFF0C\u56DB\u5468\u662F\u642D\u7740\u7BF7\u5E03\u7684\u644A\u4F4D\u3002"},{en:"Glass, lace and carpets change hands here.",zh:"\u73BB\u7483\u3001\u857E\u4E1D\u4E0E\u5730\u6BEF\u5728\u8FD9\u91CC\u4E70\u5356\u3002"},{confidence:"low",refs:["awoiaf"],book:{en:"Myr is a trading city with famous exports; a central square is an assumption.",zh:"\u5BC6\u5C14\u662F\u5546\u8D38\u57CE\u90A6\uFF0C\u51FA\u53E3\u540D\u54C1\u4F17\u591A\uFF1B\u4E2D\u592E\u5E7F\u573A\u53EA\u662F\u63A8\u6D4B\u3002"},unknown:{en:"Where trade actually happens.",zh:"\u4EA4\u6613\u5B9E\u9645\u5728\u4F55\u5904\u8FDB\u884C\u3002"},interpretation:{en:"Fourteen awninged stalls around a small fountain.",zh:"\u5C0F\u55B7\u6CC9\u56DB\u5468\u7684\u5341\u56DB\u4E2A\u7BF7\u5E03\u644A\u4F4D\u3002"}}),"magisters-hall":e({en:"Magisters' Hall",zh:"\u603B\u7763\u8BAE\u4E8B\u5385"},{en:"A marble hall with a brass dome, imagined as the meeting place of the ruling magisters.",zh:"\u4E00\u5EA7\u9EC4\u94DC\u7A79\u9876\u7684\u5927\u7406\u77F3\u6BBF\u5802\uFF0C\u8BBE\u60F3\u4E3A\u6267\u638C\u57CE\u90A6\u7684\u603B\u7763\u4EEC\u8BAE\u4E8B\u4E4B\u6240\u3002"},{en:"A conclave of wealthy magisters rules Myr; this is where it might sit.",zh:"\u5BCC\u6709\u7684\u603B\u7763\u8BAE\u4F1A\u7EDF\u6CBB\u7740\u5BC6\u5C14\uFF0C\u6216\u8BB8\u5C31\u5728\u8FD9\u91CC\u8BAE\u4E8B\u3002"},{confidence:"low",refs:["awoiaf"],book:{en:"Myr is governed by a conclave of magisters drawn from its richest and noblest men (wiki summary); no hall is described.",zh:"\u636E\u7EF4\u57FA\u6458\u8981\uFF0C\u5BC6\u5C14\u7531\u4ECE\u6700\u5BCC\u6709\u3001\u6700\u663E\u8D35\u8005\u4E2D\u9009\u51FA\u7684\u603B\u7763\u8BAE\u4F1A\u6CBB\u7406\uFF1B\u4E66\u4E2D\u672A\u63CF\u5199\u4EFB\u4F55\u6BBF\u5802\u3002"},unknown:{en:"Where and how they meet.",zh:"\u8BAE\u4E8B\u5730\u70B9\u4E0E\u65B9\u5F0F\u3002"},interpretation:{en:"An invented hall facing the market square.",zh:"\u81EA\u62DF\u7684\u6BBF\u5802\uFF0C\u9762\u671D\u5E02\u96C6\u5E7F\u573A\u3002"}}),"lens-makers-quarter":e({en:"Lens-makers' Quarter",zh:"\u78E8\u955C\u5E08\u8857\u533A"},{en:"Rows of glass-roofed workshops where lenses are ground, the craft that made Myr famous.",zh:"\u4E00\u6392\u6392\u73BB\u7483\u5C4B\u9876\u7684\u4F5C\u574A\uFF0C\u78E8\u5236\u955C\u7247\u2014\u2014\u5BC6\u5C14\u6B63\u662F\u51ED\u8FD9\u95E8\u624B\u827A\u626C\u540D\u3002"},{en:"Myrish lenses reach as far as the Wall.",zh:"\u5BC6\u5C14\u955C\u7247\u4E00\u8DEF\u8FDC\u9500\u5230\u4E86\u957F\u57CE\u3002"},{confidence:"high",refs:["asos","awoiaf"],book:{en:"Myrish lenses and far-eyes are prized and appear in Westeros in the novels.",zh:"\u5BC6\u5C14\u955C\u7247\u4E0E\u8FDC\u955C\u5907\u53D7\u73CD\u89C6\uFF0C\u5C0F\u8BF4\u4E2D\u5728\u7EF4\u65AF\u7279\u6D1B\u5C61\u6709\u51FA\u73B0\u3002"},unknown:{en:"Where in the city the craft is practised.",zh:"\u8FD9\u95E8\u624B\u827A\u5728\u57CE\u4E2D\u4F55\u5904\u65BD\u5C55\u3002"},interpretation:{en:"Eight glass-roofed workshops in one block; the glass roofs are invented.",zh:"\u540C\u4E00\u8857\u533A\u91CC\u7684\u516B\u95F4\u4F5C\u574A\uFF1B\u73BB\u7483\u5C4B\u9876\u7CFB\u81EA\u62DF\u3002"}}),"myrish-eye-tower":e({en:"Myrish Eye Tower",zh:"\u5BC6\u5C14\u8FDC\u955C\u5854"},{en:"A tall brick tower topped by a brass far-eye: an observatory the city never needed, but might have built.",zh:"\u4E00\u5EA7\u9AD8\u7816\u5854\uFF0C\u5854\u9876\u67B6\u7740\u9EC4\u94DC\u8FDC\u955C\u3002\u8FD9\u5EA7\u89C2\u6D4B\u53F0\u57CE\u91CC\u672A\u5FC5\u9700\u8981\uFF0C\u5374\u672A\u5C1D\u4E0D\u4F1A\u5EFA\u3002"},{en:"A far-eye atop a tower: the city's craft turned to stars and sea.",zh:"\u5854\u9876\u4E00\u67B6\u8FDC\u955C\uFF1A\u672C\u57CE\u7684\u624B\u827A\u8F6C\u5411\u661F\u7A7A\u4E0E\u5927\u6D77\u3002"},{confidence:"low",refs:["awoiaf"],book:{en:"The Myrish far-eye is a known kind of telescope; a tower for one is invented.",zh:"\u5BC6\u5C14\u8FDC\u955C\u662F\u4E00\u79CD\u6709\u540D\u7684\u671B\u8FDC\u955C\uFF1B\u4E3A\u5B83\u800C\u5EFA\u7684\u5854\u5219\u662F\u865A\u6784\u3002"},unknown:{en:"Everything about any such tower.",zh:"\u6B64\u7C7B\u5854\u7684\u4E00\u5207\u3002"},interpretation:{en:"A decorative landmark.",zh:"\u88C5\u9970\u6027\u5730\u6807\u3002"}}),glassworks:e({en:"Glassworks",zh:"\u73BB\u7483\u5DE5\u574A"},{en:"Kilns and chimneys where glass and mirrors are made.",zh:"\u70E7\u5236\u73BB\u7483\u4E0E\u955C\u5B50\u7684\u7A91\u7089\u548C\u70DF\u56F1\u3002"},{en:"The kilns burn day and night.",zh:"\u7A91\u706B\u663C\u591C\u4E0D\u7184\u3002"},{confidence:"medium",refs:["awoiaf"],book:{en:"Myr is famed for its glass and mirrors.",zh:"\u5BC6\u5C14\u4EE5\u73BB\u7483\u4E0E\u955C\u5B50\u95FB\u540D\u3002"},unknown:{en:"Where the works stand.",zh:"\u5DE5\u574A\u4F4D\u7F6E\u3002"},interpretation:{en:"Five brick kilns in the north-east corner of the walls.",zh:"\u57CE\u5899\u4E1C\u5317\u89D2\u7684\u4E94\u5EA7\u7816\u7A91\u3002"}}),"carpet-weavers":e({en:"Carpet Weavers' Yard",zh:"\u7EC7\u6BEF\u573A"},{en:"An open yard where finished carpets are laid out to dry and to be shown.",zh:"\u4E00\u7247\u5F00\u9614\u573A\u9662\uFF0C\u7EC7\u597D\u7684\u5730\u6BEF\u94FA\u5728\u8FD9\u91CC\u667E\u6652\u3001\u5C55\u793A\u3002"},{en:"Carpets and lace are among Myr's best-known exports.",zh:"\u5730\u6BEF\u4E0E\u857E\u4E1D\u662F\u5BC6\u5C14\u6700\u6709\u540D\u7684\u51FA\u53E3\u8D27\u3002"},{confidence:"medium",refs:["agot","awoiaf"],book:{en:"Myrish carpets and lace are named among the city's famous goods.",zh:"\u5BC6\u5C14\u5730\u6BEF\u4E0E\u857E\u4E1D\u90FD\u662F\u8BE5\u57CE\u7684\u540D\u4EA7\u3002"},unknown:{en:"Where the weavers work.",zh:"\u7EC7\u5DE5\u5728\u4F55\u5904\u52B3\u4F5C\u3002"},interpretation:{en:"Eighteen patterned carpets laid out in rows, with hanging racks.",zh:"\u5341\u516B\u5757\u82B1\u7EB9\u5730\u6BEF\u6210\u6392\u94FA\u5F00\uFF0C\u65C1\u8BBE\u667E\u6302\u67B6\u3002"}}),"mercenary-camps":e({en:"Mercenary Camps",zh:"\u4F63\u5175\u8425\u5730"},{en:"Free companies camp outside the walls, hired to fight the city's wars.",zh:"\u81EA\u7531\u4F63\u5175\u56E2\u9A7B\u624E\u57CE\u5916\uFF0C\u53D7\u96C7\u66FF\u672C\u57CE\u6253\u4ED7\u3002"},{en:"Myr prefers to hire others to bleed for it.",zh:"\u5BC6\u5C14\u5B81\u613F\u82B1\u94B1\u96C7\u522B\u4EBA\u66FF\u81EA\u5DF1\u6D41\u8840\u3002"},{confidence:"medium",refs:["twoiaf","awoiaf"],book:{en:"Myr fights Lys and Tyrosh over the Disputed Lands largely through hired free companies.",zh:"\u5BC6\u5C14\u4E0E\u91CC\u65AF\u3001\u6CF0\u6D1B\u897F\u4E89\u593A\u4E89\u8BAE\u4E4B\u5730\uFF0C\u4E3B\u8981\u9760\u96C7\u6765\u7684\u81EA\u7531\u4F63\u5175\u56E2\u4F5C\u6218\u3002"},unknown:{en:"Which companies, and where they camp.",zh:"\u5177\u4F53\u662F\u54EA\u4E9B\u4F63\u5175\u56E2\uFF0C\u9A7B\u624E\u4F55\u5904\u3002"},interpretation:{en:"Three rings of tents with coloured banners; the companies are generic.",zh:"\u4E09\u5708\u5E10\u7BF7\u4E0E\u5F69\u65D7\uFF1B\u4F63\u5175\u56E2\u5747\u4E3A\u6CDB\u6307\u3002"}})}};export{o as default};
